!function(e){function n(n){for(var t,a,o=n[0],p=n[1],c=n[2],l=0,s=[];l<o.length;l++)a=o[l],Object.prototype.hasOwnProperty.call(m,a)&&m[a]&&s.push(m[a][0]),m[a]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(d&&d(n);s.length;)s.shift()();return i.push.apply(i,c||[]),r()}function r(){for(var e,n=0;n<i.length;n++){for(var r,a=i[n],o=!0,p=1;p<a.length;p++)r=a[p],0!==m[r]&&(o=!1);o&&(i.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},m={39:0},i=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var d=p;i.push([198,0]),r()}({198:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(199),r(1))},199:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"75mm le.IG18型步兵炮","description":"<p>75mm le.IG18型步兵炮是二战期间德国国防军的标准配备轻型火炮，其具有轻便、直射的特点，是德国步兵在战场上直接与对手博杀的重要武器。75mm le.IG18步兵炮在二战前已投入生产并装备德国国防军，二战爆发时，该炮已有近3000门在德军中服役，1941-1942年，德国每年生产1000多门75mm le.IG18步兵炮装备德国陆军部队，在战场上，该炮主要用于杀伤集群冲锋的对手和攻击简单的防御工事，偶而也会被迫作反坦克作战，但也只能对付一些轻型坦克和装甲车；由于是直接在战场前线作战，所以该炮的战损率相当高。二战期间，德军共装备有8200多门75mm le.IG18步兵炮，到了二战快结束的1945年3月，就只剩下2500多门还跟随部队作战了。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonIG18_11.jpg","description":"<h6>75mm le.IG18型步兵炮</h6><p></p><p>技术数据：</p><p>火炮口径：75mm；</p><p>炮管长：0.88米；</p><p>火炮重：战斗0.44吨，运输：马拉0.4吨，机动车牵引：0.57吨；</p><p>火炮射界（水平方向）：11度，火炮射角（垂直方向）：-10～+75度；</p><p>射速：8～12发/分钟；</p><p>最远射程：4600米，有效射程：3550米。</p>","caption":""}],"part2title":"战场上的75mm le.IG18型步兵炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonIG18_21.jpg","description":"德军一门75mm le.IG18步兵炮的炮班成员与安放在白雪皑皑地面上的步兵炮合影。这种炮一般用于装备步兵师的炮兵连，直接在战场前沿作步兵的火力支援。图中这门炮安装了木制辐条轮，是适于用马车或骡马牵引运输的一门炮。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_22.jpg","description":"1939年，二战爆发前夕，正在进行射击瞄准训练的德军一门75mm le.IG18步兵炮。对于操纵75mm步兵炮的士兵来说，如何做到快速有效的射击是在战场上生存的关键。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_23.jpg","description":"德国武装党卫军的一门75mm le.IG18步兵炮炮组人员正在驻扎地为火炮作伪装，这门炮的炮盾上已固定了不少树叶，地上还有一些用来放置炮弹的柳条容器。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_24.jpg","description":"正在雪地上作战斗准备的一门德军75mm le.IG18步兵炮。图中可见该炮安装的是带充气轮胎的钢制盘式车轮，是适用于汽车牵引运输的。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_25.jpg","description":"1942年7月，东线苏联战场，在俄罗斯一个小城市的街道上爆发激战，德军一门75mm le.IG18步兵炮正在射击，用重火力配合步兵的进攻。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_26.jpg","description":"1942年冬季，东线苏联战场，一门75mm le.IG18步兵炮的炮组人员正为该炮转移阵地，由于无牵引车辆和马车，士兵正准备将该炮拆卸为6份，由人来搬运。注：该车带有木辐轮，适用于马车或骡马牵引运输。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_27.jpg","description":"东线苏联战场，德军的一个炮连正在紧张忙碌地将两门75mm le.IG18步兵炮和一门105mm榴弹炮移动到林间公路上，构筑一个多门炮组成的防御工事，准备迎击敌人。注意：从炮班士兵们穿着的伪装头盔罩和工作服，以及他们的衣领标识上可知这是支武装党卫军部队。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_28.jpg","description":"1944年初春，一群党卫军士兵正努力地协助牵引车将一门德军75mm le.IG18步兵炮拉过泥泞路。在二战后期，德国党卫军部队仍在使用这种轻步兵炮，在步兵防御和进攻时作近距离火力支援用。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_29.jpg","description":"东线苏联战场，在大草原上，德军一门75mm le.IG18步兵炮的炮组成员正警惕地注视前方，随时准备投入战斗。75mm le.IG18型步兵炮的优势是炮身低矮，易于隐蔽，但由于口径小，炮弹亦无穿甲能力，所以无法对苏军的中型坦克造成威胁。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_30.jpg","description":"东线苏联战场，一门德国武装党卫军炮兵连的75mm le.IG18步兵炮架设在树林边，炮组人员正瞄准前方目标准备开火，炮组指挥官用双筒望远镜注视着目标的踪迹。请注意，由于他们急着应战，没有时间构筑工事，为了稳定炮身，一名士兵直接用身体压住了炮架尾锄。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_31.jpg","description":"东线苏联战场，德军一门75mm le.IG18步兵炮刚刚开火，一名士兵用双手压着炮架尾锄，另一个士兵则紧扶车轮以帮助稳固该炮。同时，蹲着的一名炮组指挥官正使用双筒望远镜观看射击效果。","caption":""},{"image":"imgs/de/army/de_army_cannonIG18_32.jpg","description":"东线苏联战场，一门德军75mm le.IG18步兵炮的炮组人员正在迅速转移阵地，该炮指挥官已冲向前面，其余炮组人员则紧追不舍；对75mm le.IG18步兵炮的炮组人员来说，在激烈战斗中随时都要根据战况作进行转移，为了保住性命，每分每秒都是不能拖延的。","caption":""}]}')}});